notes.back:
// Why: Check the highest band first and return early: each later `if` then only sees
// scores below the previous threshold. Test every boundary (90, 89, 80, …).
// Docs: https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Statements/if...else
function letterGrade(score) {
  if (score >= 90) return "A";
  if (score >= 80) return "B";
  if (score >= 70) return "C";
  return "F";
}

