notes.back:
// Why: The falsy values are false, 0, -0, 0n, "", null, undefined and NaN. Everything else
// is truthy, including [], {} and the strings "0" and "false".
// Docs: https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects/Array/filter
function countTruthy(values) {
  return values.filter(Boolean).length;
